// NewUser initializes result type User from viewed result type User.
func NewUser(vres *userviews.User) *User {
	var res *User
	switch vres.View {
	case "default", "":
		res = newUser(vres.Projected)
	case "minimal":
		res = newUserMinimal(vres.Projected)
	case "public":
		res = newUserPublic(vres.Projected)
	}
	return res
}

// NewViewedUser initializes viewed result type User from result type User
// using the given view.
func NewViewedUser(res *User, view string) *userviews.User {
	var vres *userviews.User
	switch view {
	case "default", "":
		p := newUserView(res)
		vres = &userviews.User{Projected: p, View: "default"}
	case "minimal":
		p := newUserViewMinimal(res)
		vres = &userviews.User{Projected: p, View: "minimal"}
	case "public":
		p := newUserViewPublic(res)
		vres = &userviews.User{Projected: p, View: "public"}
	}
	return vres
}

// NewUserPermissions initializes result type UserPermissions from viewed
// result type UserPermissions.
func NewUserPermissions(vres *userviews.UserPermissions) *UserPermissions {
	return newUserPermissions(vres.Projected)
}

// NewViewedUserPermissions initializes viewed result type UserPermissions from
// result type UserPermissions using the given view.
func NewViewedUserPermissions(res *UserPermissions, view string) *userviews.UserPermissions {
	p := newUserPermissionsView(res)
	return &userviews.UserPermissions{Projected: p, View: "default"}
}

// newUser converts projected type User to service type User.
func newUser(vres *userviews.UserView) *User {
	res := &User{
		Username:    vres.Username,
		DisplayName: vres.DisplayName,
		Phone:       vres.Phone,
		LastLoginAt: vres.LastLoginAt,
	}
	if vres.ID != nil {
		res.ID = *vres.ID
	}
	if vres.Email != nil {
		res.Email = *vres.Email
	}
	if vres.FirstName != nil {
		res.FirstName = *vres.FirstName
	}
	if vres.LastName != nil {
		res.LastName = *vres.LastName
	}
	if vres.Status != nil {
		res.Status = AccountStatus(*vres.Status)
	}
	if vres.UserType != nil {
		res.UserType = UserType(*vres.UserType)
	}
	if vres.PersonType != nil {
		personType := PersonType(*vres.PersonType)
		res.PersonType = &personType
	}
	if vres.EmploymentStatus != nil {
		employmentStatus := EmploymentStatus(*vres.EmploymentStatus)
		res.EmploymentStatus = &employmentStatus
	}
	if vres.CreatedAt != nil {
		res.CreatedAt = *vres.CreatedAt
	}
	if vres.UpdatedAt != nil {
		res.UpdatedAt = *vres.UpdatedAt
	}
	if vres.Profile != nil {
		res.Profile = transformUserviewsUserProfileViewToUserProfile(vres.Profile)
	}
	if vres.Preferences != nil {
		res.Preferences = transformUserviewsUserPreferencesViewToUserPreferences(vres.Preferences)
	}
	return res
}

