// transformUserviewsPermissionInfoViewToPermissionInfo builds a value of type
// *PermissionInfo from a value of type *userviews.PermissionInfoView.
func transformUserviewsPermissionInfoViewToPermissionInfo(v *userviews.PermissionInfoView) *PermissionInfo {
	if v == nil {
		return nil
	}
	res := &PermissionInfo{
		Resource:   *v.Resource,
		Action:     ActionType(*v.Action),
		Effect:     *v.Effect,
		SourceRole: v.SourceRole,
	}
	if v.Conditions != nil {
		res.Conditions = make(map[string]any, len(v.Conditions))
		for key, val := range v.Conditions {
			tk := key
			tv := val
			res.Conditions[tk] = tv
		}
	}

	return res
}

// transformRoleInfoToUserviewsRoleInfoView builds a value of type
// *userviews.RoleInfoView from a value of type *RoleInfo.
func transformRoleInfoToUserviewsRoleInfoView(v *RoleInfo) *userviews.RoleInfoView {
	res := &userviews.RoleInfoView{
		ID:          &v.ID,
		Name:        &v.Name,
		Description: v.Description,
		AssignedAt:  &v.AssignedAt,
		ExpiresAt:   v.ExpiresAt,
	}
	roleType := userviews.RoleTypeView(v.RoleType)
	res.RoleType = &roleType
	assignmentType := userviews.AssignmentTypeView(v.AssignmentType)
	res.AssignmentType = &assignmentType

	return res
}

// transformPermissionInfoToUserviewsPermissionInfoView builds a value of type
// *userviews.PermissionInfoView from a value of type *PermissionInfo.
func transformPermissionInfoToUserviewsPermissionInfoView(v *PermissionInfo) *userviews.PermissionInfoView {
	res := &userviews.PermissionInfoView{
		Resource:   &v.Resource,
		Effect:     &v.Effect,
		SourceRole: v.SourceRole,
	}
	action := userviews.ActionTypeView(v.Action)
	res.Action = &action
	if v.Conditions != nil {
		res.Conditions = make(map[string]any, len(v.Conditions))
		for key, val := range v.Conditions {
			tk := key
			tv := val
			res.Conditions[tk] = tv
		}
	}

	return res
}
